import React from 'react';
import ReactDOM from 'react-dom';
import {
  DataTable,
  TableContainer,
  TableToolbar,
  TableToolbarSearch,
  TableToolbarContent,
  TableToolbarAction,
  Table,
  TableHead,
  TableRow,
  TableHeader,
  TableBody,
  TableCell,
  Button,
} from 'carbon-components-react';
import { Download16, Edit16, Settings16 } from '@carbon/icons-react';

const headers = [
  { key: 'name', header: 'Name' },
  { key: 'protocol', header: 'Protocol' },
  { key: 'port', header: 'Port' },
  { key: 'rule', header: 'Rule' },
  { key: 'attachedGroups', header: 'Attached Groups' },
  { key: 'status', header: 'Status' },
];

const rows = [
  {
    id: 'a',
    name: 'Load Balancer 1',
    protocol: 'HTTP',
    port: 3000,
    rule: 'Round robin',
    attachedGroups: 'Kevins VM Groups',
    status: 'Disabled',
  },
  {
    id: 'b',
    name: 'Load Balancer 2',
    protocol: 'HTTPS',
    port: 443,
    rule: 'Round robin',
    attachedGroups: 'Maureens VM Groups',
    status: 'Starting',
  },
];

function DataTableWithToolbar() {
  return (
    // constrain width to force toolbar overflow
    <div style={{ width: '360px', border: '1px solid #ddd', padding: '8px' }}>
      <DataTable rows={rows} headers={headers} isSortable render={({ rows, headers, getHeaderProps, onInputChange }) => (
        <TableContainer title="DataTable">
          <TableToolbar>
            <TableToolbarSearch onChange={onInputChange} />
            <TableToolbarContent>
              <TableToolbarAction
                icon={Download16}
                iconDescription="Download"
                onClick={() => console.log('Download')}
              />
              <TableToolbarAction
                icon={Edit16}
                iconDescription="Edit"
                onClick={() => console.log('Edit')}
              />
              <TableToolbarAction
                icon={Settings16}
                iconDescription="Settings"
                onClick={() => console.log('Settings')}
              />
              <Button kind="primary" size="small">
                Primary Button
              </Button>
            </TableToolbarContent>
          </TableToolbar>
          <Table>
            <TableHead>
              <TableRow>
                {headers.map(header => (
                  <TableHeader {...getHeaderProps({ header })} key={header.key}>
                    {header.header}
                  </TableHeader>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map(row => (
                <TableRow key={row.id}>
                  {row.cells.map(cell => (
                    <TableCell key={cell.id}>{cell.value}</TableCell>
                  ))}
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )} />
    </div>
  );
}

ReactDOM.render(<DataTableWithToolbar />, document.getElementById('root'));
